def after(path: str, anchor: str, old: str, new: str) -> tuple[str, str, str]:
    """An edit to the first `old` that follows the first `anchor`: the pattern is cut from the file itself, so it is exact and unique."""
    text = (REPO / path).read_text(encoding="utf-8")
    start = text.index(anchor)
    end = text.index(old, start) + len(old)
    segment = text[start:end]
    return (path, segment, segment[: -len(old)] + new)


